import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';

const HeroSection = styled.section`
  height: 100vh;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: #000;
`;

const VideoBackground = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;

  &::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.3);
    z-index: 2;
  }
`;

const Video = styled.video`
  width: 100%;
  height: 100%;
  object-fit: cover;
`;

const HeroContent = styled(motion.div)`
  position: relative;
  z-index: 3;
  text-align: center;
  color: #fff;
  max-width: 800px;
  padding: 0 20px;
`;

const MainTitle = styled(motion.h1)`
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 300;
  line-height: 1.1;
  margin-bottom: 30px;
  text-transform: uppercase;
  letter-spacing: -2px;
`;

const Subtitle = styled(motion.h2)`
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 300;
  margin-bottom: 40px;
  opacity: 0.9;
`;

const ScrollIndicator = styled(motion.div)`
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  color: #fff;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  cursor: pointer;
  z-index: 3;

  &::after {
    content: '';
    position: absolute;
    top: 30px;
    left: 50%;
    transform: translateX(-50%);
    width: 1px;
    height: 40px;
    background: #fff;
    animation: scroll 2s infinite;
  }

  @keyframes scroll {
    0% { transform: translateX(-50%) scaleY(0); transform-origin: top; }
    50% { transform: translateX(-50%) scaleY(1); transform-origin: top; }
    100% { transform: translateX(-50%) scaleY(0); transform-origin: bottom; }
  }
`;

const Hero = () => {
  const [currentSlide, setCurrentSlide] = useState(0);

  const slides = [
    {
      title: "Fazendo uma diferença",
      subtitle: "significativa para marcas, negócios e pessoas",
      video: "https://www.havas.com/wp-content/uploads/2023/12/Havas-Homepage-Hero-Video.mp4"
    },
    {
      title: "Criatividade que",
      subtitle: "transforma e inspira",
      video: "https://www.havas.com/wp-content/uploads/2023/12/Havas-Homepage-Hero-Video.mp4"
    },
    {
      title: "Comunicação que",
      subtitle: "conecta e engaja",
      video: "https://www.havas.com/wp-content/uploads/2023/12/Havas-Homepage-Hero-Video.mp4"
    }
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 5000);

    return () => clearInterval(interval);
  }, [slides.length]);

  const handleScrollDown = () => {
    window.scrollTo({
      top: window.innerHeight,
      behavior: 'smooth'
    });
  };

  return (
    <HeroSection>
      <VideoBackground>
        <Video autoPlay muted loop playsInline>
          <source src={slides[currentSlide].video} type="video/mp4" />
          Seu navegador não suporta vídeos.
        </Video>
      </VideoBackground>

      <HeroContent>
        <MainTitle
          key={currentSlide}
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -50 }}
          transition={{ duration: 0.8 }}
        >
          {slides[currentSlide].title}
        </MainTitle>

        <Subtitle
          key={`subtitle-${currentSlide}`}
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -30 }}
          transition={{ duration: 0.8, delay: 0.2 }}
        >
          {slides[currentSlide].subtitle}
        </Subtitle>
      </HeroContent>

      <ScrollIndicator
        onClick={handleScrollDown}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1, duration: 1 }}
      >
        Role para baixo
      </ScrollIndicator>
    </HeroSection>
  );
};

export default Hero;
